export function slugify(title) {
  // Trim leading/trailing whitespace and convert to lowercase
  let result = title.trim().toLowerCase();

  // Replace any character that is NOT a unicode letter (L) or unicode number (N) with '-'
  result = result.replace(/[^\p{L}\p{N}]/gu, '-');

  // Collapse multiple consecutive hyphens into one
  result = result.replace(/-+/g, '-');

  // Remove leading or trailing hyphens
  result = result.replace(/^-|-$/g, '');

  // Return 'item' as default fallback for empty string results
  if (result === '') {
    return 'item';
  }

  return result;
}"}

